PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT ?assessment_pathway
       (COUNT(DISTINCT ?g) AS ?patients)
       (IF(SUM(?assessed) > 0, ROUND(1.0 * SUM(?days_to_first_assessment) / SUM(?assessed)), "")
         AS ?avg_days_to_first_assessment)
WHERE {
  {
    SELECT ?g (MIN(?incidence) AS ?diagnosed)
              (MIN(?grading_date) AS ?first_grading)
              (MIN(?staging_date) AS ?first_staging)
    WHERE {
      GRAPH ?g {
        ?dx a sphn:OncologyDiagnosis ;
            sphn:hasIncidenceDateTime ?incidence .
      }
      OPTIONAL {
        GRAPH ?g {
          ?dx sphn:hasIncidenceDateTime ?incidence .
          ?grading a sphn:TumorGradeAssessmentEvent ; sphn:hasDateTime ?grading_date .
        }
        FILTER (?grading_date > ?incidence)
      }
      OPTIONAL {
        GRAPH ?g {
          ?dx sphn:hasIncidenceDateTime ?incidence .
          ?staging a sphn:TumorStageAssessmentEvent ; sphn:hasDateTime ?staging_date .
        }
        FILTER (?staging_date > ?incidence)
      }
    }
    GROUP BY ?g
  }
  BIND (IF(BOUND(?first_grading) && BOUND(?first_staging), "graded and staged",
        IF(BOUND(?first_grading), "graded only",
        IF(BOUND(?first_staging), "staged only", "no grading or staging after diagnosis"))) AS ?assessment_pathway)
  BIND (IF(BOUND(?first_grading) && BOUND(?first_staging),
           IF(?first_grading < ?first_staging, ?first_grading, ?first_staging),
           COALESCE(?first_grading, ?first_staging)) AS ?first_assessment)
  BIND (IF(BOUND(?first_assessment), 1, 0) AS ?assessed)
  BIND (bif:datediff("day", ?diagnosed, COALESCE(?first_assessment, ?diagnosed)) AS ?days_to_first_assessment)
}
GROUP BY ?assessment_pathway
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX bif: <bif:>

SELECT ?cohort
       (COUNT(DISTINCT ?case) AS ?stays)
       (COUNT(*) AS ?encounters)
       (ROUND(AVG(?hours)) AS ?avg_hours)
       (MIN(?hours) AS ?min_hours)
       (MAX(?hours) AS ?max_hours)
       (SUM(IF(?hours <= 72, 1, 0)) AS ?within_72_hours)
       (ROUND(1000.0 * SUM(IF(?hours <= 72, 1, 0)) / COUNT(*)) / 10 AS ?within_72_hours_pct)
WHERE {
  {
    SELECT DISTINCT ?g ?case ?encounter ?start ?end
    WHERE {
      GRAPH ?g {
        ?encounter a sphn:HealthcareEncounter ;
                   sphn:hasAdministrativeCase ?case ;
                   sphn:hasStartDateTime ?start ;
                   sphn:hasEndDateTime ?end .
      }
      FILTER (?end >= ?start)
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasAdministrativeCase ?case ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "stays billed for cholera", "other stays") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>

SELECT ?sex
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?ultrasound_patient) AS ?principal_ultrasound_patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?ultrasound_patient) / COUNT(DISTINCT ?g)) / 10 AS ?principal_ultrasound_pct)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  OPTIONAL {
    GRAPH ?g {
      ?procedure a sphn:BilledProcedure ;
                 sphn:hasRank sphn-individual:Principal ;
                 sphn:hasCode ?procedure_code .
      ?procedure_code a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?ultrasound_patient)
  }
}
GROUP BY ?sex
ORDER BY DESC(?principal_ultrasound_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_birth_and_home_country)
       (COUNT(DISTINCT ?moved_patient) AS ?living_outside_birth_country)
       (ROUND(1000.0 * COUNT(DISTINCT ?moved_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g {
    ?birth a sphn:Birth ;
           sphn:hasCountry ?birth_country .
    ?birth_country a sphn:Country ;
                   sphn:hasCode ?birth_code .
    ?birth_code a ?birth_country_concept .
    ?home a sphn:HomeAddress ;
          sphn:hasCountry ?home_country .
  }
  VALUES ?country_root { snomed:223369002 snomed:223860005 }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?birth_country_concept rdfs:subClassOf* ?country_root .
  }
  BIND (IF(NOT EXISTS {
             GRAPH ?g {
               ?any_home a sphn:HomeAddress ;
                         sphn:hasCountry ?residence_country .
               ?residence_country sphn:hasCode ?residence_code .
               ?residence_code a ?birth_country_concept .
             }
           }, ?g, ?lives_in_birth_country) AS ?moved_patient)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?episode_agreement (COUNT(*) AS ?allergies) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  {
    SELECT ?g ?allergy (MAX(?had_episode) AS ?any_episode) (MAX(?same_allergen) AS ?any_match)
    WHERE {
      GRAPH ?g {
        ?allergy a sphn:Allergy ;
                 sphn:hasAllergen ?allergen .
        ?allergen sphn:hasCode ?allergen_code .
        ?allergen_code a ?allergen_concept .
        FILTER (STRSTARTS(STR(?allergen_concept), "http://snomed.info/id/"))
        OPTIONAL {
          ?episode a sphn:AllergyEpisode ;
                   sphn:hasAllergen ?episode_allergen .
          ?episode_allergen sphn:hasCode ?episode_allergen_code .
          ?episode_allergen_code a ?episode_allergen_concept .
          FILTER (STRSTARTS(STR(?episode_allergen_concept), "http://snomed.info/id/"))
        }
      }
      BIND (IF(BOUND(?episode), 1, 0) AS ?had_episode)
      BIND (IF(BOUND(?episode) && ?allergen_concept = ?episode_allergen_concept, 1, 0) AS ?same_allergen)
    }
    GROUP BY ?g ?allergy
  }
  BIND (IF(?any_match = 1, "1: episode with the same allergen",
        IF(?any_episode = 1, "2: episodes with other allergens only",
                             "3: no allergy episode recorded")) AS ?episode_agreement)
}
GROUP BY ?episode_agreement
ORDER BY ?episode_agreement

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX bif: <bif:>

SELECT ?radiotherapy_concept (SAMPLE(?label) AS ?radiotherapy)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?curative_patient) AS ?patients_with_curative_intent)
       (ROUND(AVG(?duration_hours)) AS ?avg_duration_hours)
WHERE {
  GRAPH ?g {
    ?procedure a sphn:RadiotherapyProcedure ;
               sphn:hasStartDateTime ?start ;
               sphn:hasEndDateTime ?end ;
               sphn:hasCode ?code .
    ?code a ?radiotherapy_concept .
  }
  FILTER (STRSTARTS(STR(?radiotherapy_concept), "http://snomed.info/id/"))
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?radiotherapy_concept rdfs:label ?label . }
    FILTER (LANGMATCHES(LANG(?label), "en"))
  }
  OPTIONAL {
    GRAPH ?curative_patient {
      ?procedure sphn:hasIntent ?intent .
      ?intent sphn:hasCode ?intent_code .
      ?intent_code a snomed:373808002 .
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?duration_hours)
}
GROUP BY ?radiotherapy_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT ?imaging_concept
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?imaging) AS ?imaging_procedures)
       (ROUND(1000.0 * SUM(?during_stay) / COUNT(?imaging)) / 10 AS ?started_during_hospital_stay_pct)
       (ROUND(AVG(?duration_hours)) AS ?avg_duration_hours)
WHERE {
  GRAPH ?g {
    ?imaging a sphn:ImagingProcedure ;
             sphn:hasAdministrativeCase ?case ;
             sphn:hasCode ?imaging_code ;
             sphn:hasStartDateTime ?start ;
             sphn:hasEndDateTime ?end .
    ?imaging_code a ?imaging_concept .
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
  }
  FILTER (STRSTARTS(STR(?imaging_concept), "http://snomed.info/id/"))
  FILTER (?end >= ?start)
  BIND (IF(?start >= ?admission && ?start <= ?discharge, 1, 0) AS ?during_stay)
  BIND (bif:datediff("hour", ?start, ?end) AS ?duration_hours)
}
GROUP BY ?imaging_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX geno: <http://purl.obolibrary.org/obo/GENO_>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?variant_type
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?germline_patient) AS ?patients_germline)
       (COUNT(DISTINCT ?somatic_patient) AS ?patients_somatic)
       (COUNT(DISTINCT ?cholera_patient) AS ?patients_with_cholera_billed)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_patient) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  VALUES ?variant_class {
    sphn:SingleNucleotideVariation sphn:GenomicInsertion sphn:GenomicDeletion sphn:GenomicDelins
    sphn:GenomicDuplication sphn:GenomicInversion sphn:GenomicTranslocation sphn:GenomicTransposition
    sphn:CopyNumberVariation sphn:GeneFusion
  }
  GRAPH ?g {
    ?descriptor a sphn:VariantDescriptor ;
                sphn:hasGeneticVariation ?variant ;
                sphn:hasAlleleOriginCode ?origin_code .
    ?variant a ?variant_class .
    ?origin_code a ?origin .
  }
  BIND (STRAFTER(STR(?variant_class), "#") AS ?variant_type)
  OPTIONAL {
    GRAPH ?g { ?origin_code a geno:0000888 . }
    BIND (?g AS ?germline_patient)
  }
  OPTIONAL {
    GRAPH ?g { ?origin_code a geno:0000882 . }
    BIND (?g AS ?somatic_patient)
  }
  OPTIONAL {
    GRAPH ?g {
      ?dx a sphn:BilledDiagnosis ;
          sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?cholera_patient)
  }
}
GROUP BY ?variant_type
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?risk_level
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?confirmed_patient) AS ?patients_confirmed)
       (COUNT(DISTINCT ?refuted_patient) AS ?patients_refuted)
       (ROUND(1000.0 * COUNT(DISTINCT ?confirmed_patient) / COUNT(DISTINCT ?g)) / 10 AS ?confirmed_pct)
       (ROUND(1000.0 * COUNT(DISTINCT ?refuted_patient) / COUNT(DISTINCT ?g)) / 10 AS ?refuted_pct)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasSeverityCode ?risk_code ;
             sphn:hasVerificationStatusCode ?status_code .
    ?risk_code a ?risk_concept .
  }
  VALUES (?risk_concept ?risk_level) {
    (snomed:723505004 "low risk")
    (snomed:723509005 "high risk")
    (snomed:723507007 "unable to determine")
  }
  OPTIONAL {
    GRAPH ?g { ?status_code a snomed:410605003 . }
    BIND (?g AS ?confirmed_patient)
  }
  OPTIONAL {
    GRAPH ?g { ?status_code a snomed:723511001 . }
    BIND (?g AS ?refuted_patient)
  }
}
GROUP BY ?risk_level
ORDER BY DESC(?confirmed_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?care_type
       (COUNT(DISTINCT ?case) AS ?stays)
       (SUM(IF(?days <= 7, 1, 0)) AS ?up_to_7_days)
       (SUM(IF(?days > 7 && ?days <= 28, 1, 0)) AS ?from_8_to_28_days)
       (SUM(IF(?days > 28, 1, 0)) AS ?more_than_28_days)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_stay_days)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge ;
          sphn:hasCareHandling ?care_handling .
    ?care_handling sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?care_type) {
    (snomed:394656005 "inpatient")
    (snomed:371883000 "outpatient")
    (snomed:304903009 "day care")
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
}
GROUP BY ?care_type
ORDER BY DESC(?stays)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?procedure_code a chop:00.0 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?procedure sphn:hasCode ?procedure_code .
    ?procedure a sphn:BilledProcedure .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?radiotherapy_kind
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?radiotherapy) AS ?radiotherapy_procedures)
       (ROUND(10 * AVG(?hours)) / 10 AS ?avg_hours)
WHERE {
  {
    SELECT DISTINCT ?g ?radiotherapy ?radiotherapy_kind ?start ?end
    WHERE {
      GRAPH ?g {
        ?radiotherapy a sphn:RadiotherapyProcedure ;
                      sphn:hasCode ?code ;
                      sphn:hasStartDateTime ?start ;
                      sphn:hasEndDateTime ?end .
        ?code a ?kind_concept .
      }
      VALUES (?kind_concept ?radiotherapy_kind) {
        (snomed:33195004  "external beam radiotherapy")
        (snomed:152198000 "brachytherapy")
        (snomed:115959002 "stereotactic radiosurgery")
        (snomed:395096001 "stereotactic radiotherapy")
        (snomed:168524008 "intraoperative radiotherapy")
        (snomed:78080008  "hyperthermia")
        (snomed:399315003 "radionuclide therapy")
        (snomed:74964007  "other")
      }
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
}
GROUP BY ?radiotherapy_kind
ORDER BY DESC(?patients)
LIMIT 3

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?care_type
       (COUNT(DISTINCT ?case) AS ?stays)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days)
       (MIN(?days) AS ?min_days)
       (MAX(?days) AS ?max_days)
       (SUM(IF(?days > 60, 1, 0)) AS ?stays_over_60_days)
       (ROUND(1000.0 * SUM(IF(?days > 60, 1, 0)) / COUNT(DISTINCT ?case)) / 10 AS ?over_60_days_pct)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasCareHandling ?care_handling ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
    ?care_handling sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?care_type) {
    (snomed:394656005 "inpatient")
    (snomed:371883000 "outpatient")
    (snomed:304903009 "day care")
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
}
GROUP BY ?care_type
ORDER BY ?care_type

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?cohort
       (COUNT(DISTINCT ?case) AS ?stays_with_billed_procedure)
       (COUNT(DISTINCT ?procedure) AS ?billed_procedures)
       (SUM(?principal) AS ?principal_procedures)
       (ROUND(1000.0 * SUM(?principal) / COUNT(DISTINCT ?procedure)) / 10 AS ?principal_pct)
WHERE {
  {
    SELECT DISTINCT ?g ?case ?procedure ?rank
    WHERE {
      GRAPH ?g {
        ?procedure a sphn:BilledProcedure ;
                   sphn:hasAdministrativeCase ?case ;
                   sphn:hasRank ?rank .
      }
    }
  }
  BIND (IF(?rank = sphn-individual:Principal, 1, 0) AS ?principal)
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasAdministrativeCase ?case ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "billed for cholera", "other stays") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?specialty
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?cholera_patient) AS ?patients_with_cholera)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_patient) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  {
    SELECT DISTINCT ?g ?specialty_value
    WHERE {
      GRAPH ?g {
        ?encounter a sphn:HealthcareEncounter ;
                   sphn:hasTherapeuticArea ?area .
        ?area sphn:hasSpecialtyName ?specialty_value .
      }
    }
  }
  BIND (STRAFTER(STR(?specialty_value), "#") AS ?specialty)
  OPTIONAL {
    GRAPH ?g {
      ?dx a sphn:BilledDiagnosis ;
          sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?cholera_patient)
  }
}
GROUP BY ?specialty
ORDER BY DESC(?patients)
LIMIT 4

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?cancer_patients)
       (SUM(?had_radiotherapy) AS ?with_radiotherapy)
       (ROUND(1000.0 * SUM(?had_radiotherapy) / COUNT(DISTINCT ?g)) / 10 AS ?radiotherapy_pct)
       (SUM(?had_surgery) AS ?with_cancer_surgery)
       (ROUND(1000.0 * SUM(?had_surgery) / COUNT(DISTINCT ?g)) / 10 AS ?cancer_surgery_pct)
       (SUM(?had_radiotherapy * ?had_surgery) AS ?with_both)
       (ROUND(1000.0 * SUM(?had_radiotherapy * ?had_surgery) / COUNT(DISTINCT ?g)) / 10 AS ?both_pct)
WHERE {
  {
    SELECT DISTINCT ?g
    WHERE {
      GRAPH ?g { ?dx a sphn:OncologyDiagnosis . }
    }
  }
  BIND (IF(EXISTS { GRAPH ?g { ?radiotherapy a sphn:RadiotherapyProcedure . } }, 1, 0) AS ?had_radiotherapy)
  BIND (IF(EXISTS { GRAPH ?g { ?surgery a sphn:OncologySurgery . } }, 1, 0) AS ?had_surgery)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(AVG(?days_to_radiotherapy)) AS ?avg_days)
       (MIN(?days_to_radiotherapy) AS ?min_days)
       (MAX(?days_to_radiotherapy) AS ?max_days)
WHERE {
  {
    SELECT ?g (MIN(?incidence) AS ?diagnosed) (MIN(?radiotherapy_start) AS ?first_radiotherapy)
    WHERE {
      GRAPH ?g {
        ?dx a sphn:OncologyDiagnosis ;
            sphn:hasIncidenceDateTime ?incidence .
        ?radiotherapy a sphn:RadiotherapyProcedure ;
                      sphn:hasStartDateTime ?radiotherapy_start .
      }
      FILTER (?radiotherapy_start > ?incidence)
    }
    GROUP BY ?g
  }
  BIND (bif:datediff("day", ?diagnosed, ?first_radiotherapy) AS ?days_to_radiotherapy)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_billed_procedure)
       (COUNT(DISTINCT ?imaged_patient) AS ?with_imaging_in_30_days_before)
       (ROUND(1000.0 * COUNT(DISTINCT ?imaged_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  {
    SELECT DISTINCT ?g
    WHERE {
      GRAPH ?g { ?procedure a sphn:BilledProcedure . }
    }
  }
  OPTIONAL {
    GRAPH ?g {
      ?billed a sphn:BilledProcedure ;
              sphn:hasStartDateTime ?procedure_start .
      ?imaging a sphn:ImagingProcedure ;
               sphn:hasStartDateTime ?imaging_start .
    }
    FILTER (?imaging_start < ?procedure_start && bif:datediff("day", ?imaging_start, ?procedure_start) <= 30)
    BIND (?g AS ?imaged_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?year
       (COUNT(DISTINCT ?dx) AS ?billed_diagnoses)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?cholera_dx) AS ?cholera_diagnoses)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_dx) / COUNT(DISTINCT ?dx)) / 10 AS ?cholera_pct)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasRecordDateTime ?recorded .
  }
  BIND (YEAR(?recorded) AS ?year)
  FILTER (?year >= 2015 && ?year <= 2024)
  OPTIONAL {
    GRAPH ?g {
      ?dx sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?dx AS ?cholera_dx)
  }
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?cholera_type
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?principal_patient) AS ?patients_as_principal_diagnosis)
       (ROUND(1000.0 * COUNT(DISTINCT ?principal_patient) / COUNT(DISTINCT ?g)) / 10 AS ?principal_pct)
WHERE {
  VALUES (?subtype ?cholera_type) {
    (icd-10-gm:A00.0 "classical cholera")
    (icd-10-gm:A00.1 "El Tor cholera")
    (icd-10-gm:A00.9 "cholera, unspecified")
  }
  GRAPH ?g {
    ?dx_code a ?subtype OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?dx sphn:hasCode ?dx_code .
    ?dx a sphn:BilledDiagnosis .
  }
  OPTIONAL {
    GRAPH ?g { ?dx sphn:hasRank sphn-individual:Principal . }
    BIND (?g AS ?principal_patient)
  }
}
GROUP BY ?cholera_type
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients_with_imaging)
       (COUNT(DISTINCT ?imaging) AS ?imaging_procedures)
       (COUNT(DISTINCT ?staging_imaging) AS ?staging_procedures)
       (ROUND(1000.0 * COUNT(DISTINCT ?staging_imaging) / COUNT(DISTINCT ?imaging)) / 10 AS ?staging_pct)
WHERE {
  {
    SELECT DISTINCT ?g ?imaging
    WHERE {
      GRAPH ?g { ?imaging a sphn:ImagingProcedure . }
    }
  }
  BIND (IF(EXISTS { GRAPH ?g { ?dx a sphn:OncologyDiagnosis . } }, "cancer diagnosis", "other patients") AS ?cohort)
  OPTIONAL {
    GRAPH ?g {
      ?imaging sphn:hasIntent ?intent .
      ?intent sphn:hasCode ?intent_code .
      ?intent_code a snomed:373825000 .
    }
    BIND (?imaging AS ?staging_imaging)
  }
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_prescription)
       (COUNT(DISTINCT ?plasminogen_patient) AS ?patients_prescribed_plasminogen)
       (COUNT(DISTINCT ?plasminogen_prescription) AS ?plasminogen_prescriptions)
       (ROUND(1000.0 * COUNT(DISTINCT ?plasminogen_patient) / COUNT(DISTINCT ?g)) / 10 AS ?plasminogen_patient_pct)
WHERE {
  GRAPH ?g {
    ?prescription a sphn:DrugPrescription .
  }
  OPTIONAL {
    GRAPH ?g {
      ?prescription sphn:hasDrug ?drug .
      ?drug sphn:hasActiveIngredient ?substance .
      ?substance sphn:hasCode ?ingredient_code .
      ?ingredient_code a snomed:62252006 .
    }
    BIND (?g AS ?plasminogen_patient)
    BIND (?prescription AS ?plasminogen_prescription)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_administration)
       (ROUND(10 * AVG(?administrations)) / 10 AS ?avg_administrations_per_patient)
       (MAX(?administrations) AS ?max_administrations_per_patient)
       (ROUND(10 * AVG(?active_ingredients)) / 10 AS ?avg_active_ingredients_per_patient)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?administration) AS ?administrations)
              (COUNT(DISTINCT ?ingredient_concept) AS ?active_ingredients)
    WHERE {
      GRAPH ?g {
        ?administration a sphn:DrugAdministrationEvent .
      }
      OPTIONAL {
        GRAPH ?g {
          ?administration sphn:hasDrug ?drug .
          ?drug sphn:hasActiveIngredient ?substance .
          ?substance sphn:hasCode ?ingredient_code .
          ?ingredient_code a ?ingredient_concept .
        }
        FILTER (STRSTARTS(STR(?ingredient_concept), "http://snomed.info/id/"))
      }
    }
    GROUP BY ?g
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT ?duration_band_hours
       (COUNT(DISTINCT ?administration) AS ?administrations)
       (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?administration a sphn:DrugAdministrationEvent ;
                    sphn:hasStartDateTime ?start ;
                    sphn:hasEndDateTime ?end .
  }
  FILTER (?end >= ?start)
  BIND (24 * FLOOR(bif:datediff("hour", ?start, ?end) / 24) AS ?duration_band_hours)
}
GROUP BY ?duration_band_hours
ORDER BY ?duration_band_hours

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?reason_concept
       (SAMPLE(?label) AS ?reason)
       (COUNT(DISTINCT ?administration) AS ?administrations)
       (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?administration a sphn:DrugAdministrationEvent ;
                    sphn:hasReasonToStopCode ?reason_code .
    ?reason_code a ?reason_concept .
  }
  FILTER (STRSTARTS(STR(?reason_concept), "http://snomed.info/id/"))
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?reason_concept rdfs:label ?label . }
    FILTER (LANGMATCHES(LANG(?label), "en"))
  }
}
GROUP BY ?reason_concept
ORDER BY DESC(?administrations)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?event) AS ?lab_test_events)
       (COUNT(DISTINCT ?lab_test) AS ?lab_tests)
       (COUNT(DISTINCT ?result) AS ?lab_results)
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(10.0 * COUNT(DISTINCT ?result) / COUNT(DISTINCT ?event)) / 10 AS ?avg_results_per_event)
WHERE {
  GRAPH ?g {
    ?event a sphn:LabTestEvent ;
           sphn:hasLabTest ?lab_test .
    ?lab_test sphn:hasResult ?result .
    ?result a sphn:LabResult .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?measure
       (COUNT(DISTINCT ?record) AS ?recorded_results)
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?g) / ?all_patients) / 10 AS ?pct_of_all_patients)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?any_g) AS ?all_patients)
    WHERE {
      GRAPH ?any_g { ?any_sex_record a sphn:AdministrativeSex . }
    }
  }
  VALUES (?measure_class ?measure) {
    (sphn:BodyWeight      "body weight")
    (sphn:BodyHeight      "body height")
    (sphn:BodyMassIndex   "BMI")
    (sphn:BloodPressure   "blood pressure")
    (sphn:HeartRate       "heart rate")
    (sphn:BodyTemperature "body temperature")
  }
  GRAPH ?g { ?record a ?measure_class . }
}
GROUP BY ?measure ?all_patients
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients_with_bmi)
       (COUNT(DISTINCT ?bmi) AS ?bmi_records)
       (ROUND(10 * AVG(?bmi_value)) / 10 AS ?avg_bmi)
       (MIN(?bmi_value) AS ?min_bmi)
       (MAX(?bmi_value) AS ?max_bmi)
WHERE {
  GRAPH ?g {
    ?bmi a sphn:BodyMassIndex ;
         sphn:hasQuantity ?bmi_quantity .
    ?bmi_quantity sphn:hasValue ?bmi_value .
  }
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "cholera on a bill", "no cholera on a bill") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?readings_group
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?g) / ?all_patients) / 10 AS ?pct_of_all_patients)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?any_g) AS ?all_patients)
    WHERE {
      GRAPH ?any_g { ?any_sex_record a sphn:AdministrativeSex . }
    }
  }
  {
    SELECT ?g (COUNT(DISTINCT ?reading) AS ?readings)
    WHERE {
      GRAPH ?g { ?sex_record a sphn:AdministrativeSex . }
      OPTIONAL { GRAPH ?g { ?reading a sphn:BloodPressure . } }
    }
    GROUP BY ?g
  }
  BIND (IF(?readings = 0, "1: no reading",
        IF(?readings <= 10, "2: 1-10 readings",
        IF(?readings <= 30, "3: 11-30 readings",
        IF(?readings <= 100, "4: 31-100 readings", "5: more than 100 readings")))) AS ?readings_group)
}
GROUP BY ?readings_group ?all_patients
ORDER BY ?readings_group

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?reading) AS ?readings)
       (COUNT(DISTINCT ?suspect_reading) AS ?readings_diastolic_not_below_systolic)
       (ROUND(1000.0 * COUNT(DISTINCT ?suspect_reading) / COUNT(DISTINCT ?reading)) / 10 AS ?suspect_reading_pct)
       (COUNT(DISTINCT ?g) AS ?patients_with_readings)
       (COUNT(DISTINCT ?suspect_patient) AS ?patients_with_suspect_reading)
WHERE {
  GRAPH ?g {
    ?reading a sphn:BloodPressure .
  }
  OPTIONAL {
    GRAPH ?g {
      ?reading sphn:hasSystolicPressure ?systolic_quantity ;
               sphn:hasDiastolicPressure ?diastolic_quantity .
      ?systolic_quantity sphn:hasValue ?systolic .
      ?diastolic_quantity sphn:hasValue ?diastolic .
    }
    FILTER (?diastolic >= ?systolic)
    BIND (?reading AS ?suspect_reading)
    BIND (?g AS ?suspect_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_heart_rate)
       (COUNT(DISTINCT ?irregular_patient) AS ?patients_with_irregular_pulse)
       (ROUND(1000.0 * COUNT(DISTINCT ?irregular_patient) / COUNT(DISTINCT ?g)) / 10 AS ?irregular_patient_pct)
       (COUNT(DISTINCT ?reading) AS ?heart_rate_readings)
       (COUNT(DISTINCT ?irregular_reading) AS ?irregular_readings)
WHERE {
  GRAPH ?g {
    ?reading a sphn:HeartRate .
  }
  OPTIONAL {
    GRAPH ?g {
      ?reading sphn:hasRegularityCode ?regularity_code .
      ?regularity_code a snomed:61086009 .
    }
    BIND (?g AS ?irregular_patient)
    BIND (?reading AS ?irregular_reading)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?sex
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?deceased_patient) AS ?patients_with_death)
       (ROUND(1000.0 * COUNT(DISTINCT ?deceased_patient) / COUNT(DISTINCT ?g)) / 10 AS ?death_pct)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  OPTIONAL {
    GRAPH ?g { ?death a sphn:Death . }
    BIND (?g AS ?deceased_patient)
  }
}
GROUP BY ?sex
ORDER BY DESC(?death_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?deceased_patient) AS ?patients_with_death)
       (ROUND(1000.0 * COUNT(DISTINCT ?deceased_patient) / COUNT(DISTINCT ?g)) / 10 AS ?death_pct)
WHERE {
  GRAPH ?g { ?sex_record a sphn:AdministrativeSex . }
  BIND (IF(EXISTS { GRAPH ?g { ?event a sphn:AdverseEvent . } },
           "with an adverse event", "without an adverse event") AS ?cohort)
  OPTIONAL {
    GRAPH ?g { ?death a sphn:Death . }
    BIND (?g AS ?deceased_patient)
  }
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?reaction_type
       (COUNT(DISTINCT ?allergy) AS ?allergies)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?high_risk_allergy) AS ?high_risk_allergies)
       (ROUND(1000.0 * COUNT(DISTINCT ?high_risk_allergy) / COUNT(DISTINCT ?allergy)) / 10 AS ?high_risk_pct)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasReactionTypeCode ?reaction_code .
    ?reaction_code a ?reaction_concept .
  }
  VALUES (?reaction_concept ?reaction_type) {
    (snomed:609328004 "allergic disposition")
    (snomed:782197009 "intolerance to substance")
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasSeverityCode ?risk_code .
      ?risk_code a snomed:723509005 .
    }
    BIND (?allergy AS ?high_risk_allergy)
  }
}
GROUP BY ?reaction_type
ORDER BY DESC(?high_risk_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?sex
       (COUNT(DISTINCT ?g) AS ?patients_with_episode)
