    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  OPTIONAL {
    GRAPH ?g {
      ?episode sphn:hasSeverityCode ?severity_code .
      ?severity_code a snomed:24484000 .
    }
    BIND (?g AS ?severe_patient)
  }
}
GROUP BY ?sex
