PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_variant)
       (SUM(?no_accepted_consent) AS ?without_accepted_consent)
       (ROUND(1000.0 * SUM(?no_accepted_consent) / COUNT(DISTINCT ?g)) / 10 AS ?without_accepted_consent_pct)
WHERE {
  {
    SELECT DISTINCT ?g
    WHERE {
      GRAPH ?g { ?descriptor a sphn:VariantDescriptor . }
    }
  }
  BIND (IF(NOT EXISTS {
             GRAPH ?g {
               ?consent a sphn:Consent ;
                        sphn:hasStatusCode ?status_code .
               ?status_code a snomed:385645004 .
             }
           }, 1, 0) AS ?no_accepted_consent)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?tobacco_product
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?exposure) AS ?exposure_records)
       (ROUND(1000.0 * COUNT(DISTINCT ?g) / ?all_exposed_patients) / 10 AS ?pct_of_exposed_patients)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?any_g) AS ?all_exposed_patients)
    WHERE {
      GRAPH ?any_g { ?any_exposure a sphn:TobaccoExposure . }
    }
  }
  GRAPH ?g {
    ?exposure a sphn:TobaccoExposure ;
              sphn:hasAgentCode ?agent_code .
    ?agent_code a ?agent_concept .
  }
  VALUES (?agent_concept ?tobacco_product) {
    (snomed:66562002 "cigarettes")
    (snomed:26663004 "cigars")
    (snomed:84498003 "pipe tobacco")
    (snomed:39789004 "snuff")
    (snomed:81911001 "chewing tobacco")
    (snomed:39953003 "tobacco, unspecified")
  }
}
GROUP BY ?tobacco_product ?all_exposed_patients
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?follow_up_kind
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?follow_up) AS ?follow_ups)
       (COUNT(DISTINCT ?alive_follow_up) AS ?found_alive)
       (COUNT(DISTINCT ?lost_follow_up) AS ?lost_to_follow_up)
       (ROUND(1000.0 * COUNT(DISTINCT ?alive_follow_up) / COUNT(DISTINCT ?follow_up)) / 10 AS ?found_alive_pct)
WHERE {
  GRAPH ?g {
    ?follow_up a sphn:FollowUp ;
               sphn:hasCode ?kind_code .
    ?kind_code a ?kind_concept .
  }
  VALUES (?kind_concept ?follow_up_kind) {
    (snomed:386473003 "telephone")
    (snomed:281036007 "consultation")
  }
  OPTIONAL {
    GRAPH ?g {
      ?follow_up sphn:hasResult ?alive_status .
      ?alive_status sphn:hasCode ?alive_code .
      ?alive_code a snomed:438949009 .
    }
    BIND (?follow_up AS ?alive_follow_up)
  }
  OPTIONAL {
    GRAPH ?g {
      ?follow_up sphn:hasResult ?lost_status .
      ?lost_status sphn:hasCode ?lost_code .
      ?lost_code a snomed:399307001 .
    }
    BIND (?follow_up AS ?lost_follow_up)
  }
}
GROUP BY ?follow_up_kind
ORDER BY DESC(?found_alive_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_variant)
       (ROUND(10 * AVG(?variants)) / 10 AS ?avg_variants_per_patient)
       (MAX(?variants) AS ?max_variants_per_patient)
       (SUM(IF(?variants > 1, 1, 0)) AS ?patients_with_more_than_one)
       (ROUND(1000.0 * SUM(IF(?variants > 1, 1, 0)) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_more_than_one)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?variant) AS ?variants)
    WHERE {
      GRAPH ?g {
        ?descriptor a sphn:VariantDescriptor ;
                    sphn:hasGeneticVariation ?variant .
      }
    }
    GROUP BY ?g
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?graft_type
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?presence) AS ?transplant_episodes)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days_in_place)
       (MAX(?days) AS ?max_days_in_place)
WHERE {
  GRAPH ?g {
    ?presence a sphn:TransplantPresence ;
              sphn:hasTransplant ?transplant ;
              sphn:hasStartDateTime ?start ;
              sphn:hasEndDateTime ?end .
    ?transplant a sphn:Transplant ;
                sphn:hasGraftTypeCode ?graft_code .
    ?graft_code a ?graft_concept .
  }
  VALUES (?graft_concept ?graft_type) {
    (snomed:15879007 "own tissue")
    (snomed:7970006  "donor")
  }
  BIND (bif:datediff("day", ?start, ?end) AS ?days)
}
GROUP BY ?graft_type
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>

SELECT ?fixation_group
       (COUNT(DISTINCT ?specimen) AS ?specimens)
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?specimen) / ?all_specimens) / 10 AS ?pct_of_all_specimens)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?any_specimen) AS ?all_specimens)
    WHERE {
      GRAPH ?any_g { ?any_specimen a sphn:TumorSpecimen . }
    }
  }
  GRAPH ?g {
    ?specimen a sphn:TumorSpecimen ;
              sphn:hasFixationType ?fixation .
  }
  VALUES (?fixation ?fixation_group) {
    (sphn-individual:NeutralBufferedFormalin "formalin")
    (sphn-individual:NonbufferedFormalin     "formalin")
    (sphn-individual:SnapFreezing            "snap freezing")
  }
}
GROUP BY ?fixation_group ?all_specimens
ORDER BY DESC(?specimens)
